describe('RoleViewExportActionComponent', () => {
  let repository: RepositoryMock;
  let resourceServerRepository: RepositoryMock;
  let interactions: InteractionMocks;
  let fixture: ComponentFixture<RoleViewExportActionComponent>;
  let component: RoleViewExportActionComponent;

  beforeEach(() => {
    repository = mockRepository('RoleRepository');
    resourceServerRepository = mockRepository('ResourceServerRepository');
    interactions = configureFeatureTesting({
      declarations: [RoleViewExportActionComponent],
      repositories: [
        [RoleRepository, repository],
        [ResourceServerRepository, resourceServerRepository],
      ],
    });
    fixture = createWithoutTemplate(RoleViewExportActionComponent);
    component = fixture.componentInstance;
  });

  afterEach(() => TestBed.resetTestingModule());

  it('creates', () => {
    expect(component).toBeTruthy();
  });

  it('is the export action, without selection', () => {
    expect(component.name).toBe('export');
    expect(component.contextual).toBeFalse();
    expect(internals(component).scope).toBe('access/role');
  });

  it('exports the shared excel columns', () => {
    expect(component.definition.name).toBe('access.role');
    expect(component.definition.columns).toBe(ROLE_EXCEL_COLUMNS);
    expect(component.definition.sensitive).toBe(ROLE_EXCEL_SENSITIVE);
  });

  it('reads the acl and the pages from the repository', () => {
    component.definition.source.acl().subscribe();
    expect(repository['checkAcl']).toHaveBeenCalled();
    component.definition.source.list({} as any).subscribe();
    expect(repository['list']).toHaveBeenCalledWith({});
  });

  it('names the resourceServer references by their display', () => {
    resourceServerRepository['values'].and.returnValue(of([{ uid: 'ref-1', code: 'Shown' }]));
    let names: any;
    internals(component.definition.references)
      .resourceServer.names(['ref-1'])
      .subscribe((found: any) => (names = found));
    expect(resourceServerRepository['values']).toHaveBeenCalledWith({ uids: ['ref-1'], limit: 1 });
    expect(names).toEqual({ 'ref-1': 'Shown' });
  });
});

